"""Original teaching notes and implementations for missing upstream topics (MIT)."""

def originals():
    items = [
        ('kth-largest-element','Kth Largest Element','Heaps','Priority queue problems','Medium',
         'Given a nonempty array of integers and 1 ≤ k ≤ n, return the kth largest element, counting duplicates. For [4, 1, 7, 7, 3] with k = 2, return 7.',
         'If you keep only k candidates, which one should be easiest to evict when a better value arrives?',
         'Maintain a min-heap of at most k values. Insert each value and remove the minimum whenever the size exceeds k. The heap then contains the k largest values seen so far: a value smaller than its minimum can never enter the final top k. After the scan, the minimum of these k candidates is the kth largest. Duplicates are separate candidates. Time is O(n log k), extra space O(k).',
         '#include <vector>\n#include <queue>\n#include <functional>\n#include <stdexcept>\nusing namespace std;\n\nint kthLargest(const vector<int>& nums, int k) {\n    if (k < 1 || k > (int)nums.size()) throw invalid_argument("invalid k");\n    priority_queue<int, vector<int>, greater<int>> heap;\n    for (int x : nums) {\n        heap.push(x);\n        if ((int)heap.size() > k) heap.pop();\n    }\n    return heap.top();\n}', 'O(n log k)','O(k)'),
        ('merge-k-sorted-arrays','Merge K Sorted Arrays','Heaps','Priority queue problems','Hard',
         'Merge k sorted integer arrays into one sorted array. Empty arrays are allowed. For [[1,4], [], [2,3]], return [1,2,3,4].',
         'Only the next unused item from each array can be the next output item. How can you compare those candidates efficiently?',
         'Place the first item of every nonempty array in a min-heap together with its array index and position. Repeatedly extract the smallest candidate, append it, and insert its successor from the same array. Each candidate is the smallest remaining item in its own array, so the smallest candidate is also the globally smallest remaining item. With N total items, time is O(N log k) and auxiliary heap space is O(k), excluding the output.',
         '#include <vector>\n#include <queue>\n#include <tuple>\n#include <functional>\nusing namespace std;\n\nvector<int> mergeArrays(const vector<vector<int>>& arrays) {\n    using Item = tuple<int,int,int>;\n    priority_queue<Item, vector<Item>, greater<Item>> heap;\n    for (int i = 0; i < (int)arrays.size(); ++i)\n        if (!arrays[i].empty()) heap.emplace(arrays[i][0], i, 0);\n    vector<int> result;\n    while (!heap.empty()) {\n        auto [value, i, j] = heap.top(); heap.pop();\n        result.push_back(value);\n        if (j + 1 < (int)arrays[i].size()) heap.emplace(arrays[i][j+1], i, j+1);\n    }\n    return result;\n}', 'O(N log k)','O(k) excluding output'),
        ('min-heap-operations','Implement a Min Heap','Heaps','Heap fundamentals','Medium',
         'Implement push, top, and pop for an integer min-heap using an array. Calling top or pop on an empty heap must raise an error.',
         'In an array representation, the children of i are 2i+1 and 2i+2. Which single path can become invalid after an insertion?',
         'Store the complete binary tree in an array. Maintain the invariant that every parent is at most its children. Insert at the end and swap upward while the new value is smaller than its parent. To remove the minimum, move the last element to the root, then swap downward with the smaller child until order is restored. Insertion and removal take O(log n); looking up the minimum takes O(1). The heap stores O(n) values.',
         '#include <vector>\n#include <stdexcept>\n#include <utility>\nusing namespace std;\n\nclass MinHeap {\n    vector<int> a;\npublic:\n    void push(int x) {\n        a.push_back(x);\n        int i = (int)a.size() - 1;\n        while (i > 0 && a[i] < a[(i-1)/2]) {\n            swap(a[i], a[(i-1)/2]); i = (i-1)/2;\n        }\n    }\n    int top() const {\n        if (a.empty()) throw out_of_range("empty heap");\n        return a[0];\n    }\n    void pop() {\n        if (a.empty()) throw out_of_range("empty heap");\n        a[0] = a.back(); a.pop_back();\n        int i = 0;\n        while (2*i+1 < (int)a.size()) {\n            int child = 2*i+1;\n            if (child+1 < (int)a.size() && a[child+1] < a[child]) ++child;\n            if (a[i] <= a[child]) break;\n            swap(a[i], a[child]); i = child;\n        }\n    }\n};', 'O(log n) push/pop; O(1) top','O(n)'),
        ('assign-cookies','Assign Cookies','Greedy','Greedy basics','Easy',
         'Each child has a minimum acceptable cookie size. Each cookie can be given to one child. Return the maximum number of satisfied children. For needs [1,2,3] and cookies [1,2], return 2.',
         'Would giving the smallest sufficient cookie to the least demanding child leave more or fewer options for the others?',
         'Sort both lists. Consider children from least to most demanding and cookies from smallest to largest. If the current cookie satisfies the current child, match them and advance the child pointer. In either case advance the cookie pointer. An undersized cookie cannot satisfy any later child. Using the smallest sufficient cookie preserves larger cookies for harder-to-satisfy children, so an exchange cannot reduce the number of satisfied children.',
         '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint assignCookies(vector<int> needs, vector<int> cookies) {\n    sort(needs.begin(), needs.end());\n    sort(cookies.begin(), cookies.end());\n    int child = 0;\n    for (int cookie : cookies)\n        if (child < (int)needs.size() && cookie >= needs[child]) ++child;\n    return child;\n}', 'O(n log n + m log m)','O(n + m) for input copies'),
        ('max-nonoverlapping-meetings','Maximum Non-overlapping Meetings','Greedy','Scheduling & intervals','Medium',
         'Given meetings as [start, end) intervals with start < end, select the largest number that do not overlap. A meeting may start exactly when another ends. Return the selected count.',
         'Which first meeting leaves the most room for all future meetings: the earliest starting, shortest, or earliest finishing?',
         'Sort meetings by finishing time. Select the first available meeting, then every later meeting whose start is at least the previous selected finish. In any optimal schedule, replace its first meeting with the earliest-finishing available meeting. The replacement cannot block a later meeting because it ends no later. Apply the same argument to the remaining interval. Empty input returns zero.',
         '#include <vector>\n#include <algorithm>\n#include <limits>\nusing namespace std;\n\nint maxMeetings(vector<pair<int,int>> meetings) {\n    sort(meetings.begin(), meetings.end(), [](auto a, auto b) { return a.second < b.second; });\n    long long finish = numeric_limits<long long>::lowest();\n    int answer = 0;\n    for (auto [start, end] : meetings) {\n        if (start >= finish) { ++answer; finish = end; }\n    }\n    return answer;\n}', 'O(n log n)','O(n) input copy'),
        ('minimum-platforms','Minimum Train Platforms','Greedy','Scheduling & intervals','Medium',
         'Given equally sized arrival and departure arrays for trains, return the minimum number of platforms needed. Assume each train arrives no later than it departs. When an arrival and departure tie, the arrival needs a separate platform. For arrivals [1,2] and departures [3,4], return 2.',
         'Imagine processing all station events chronologically. What changes the number of occupied platforms?',
         'Sort arrivals and departures separately. Sweep with two pointers and count active trains. Process an arrival first when times tie, increment active, and update the maximum. Otherwise process a departure and decrement active. The maximum simultaneous occupancy is both necessary and sufficient: fewer platforms fail at that instant, and reusing a platform after every departure achieves the maximum. Empty input returns zero.',
         '#include <vector>\n#include <algorithm>\n#include <stdexcept>\nusing namespace std;\n\nint minPlatforms(vector<int> arrivals, vector<int> departures) {\n    if (arrivals.size() != departures.size()) throw invalid_argument("size mismatch");\n    sort(arrivals.begin(), arrivals.end());\n    sort(departures.begin(), departures.end());\n    int i=0, j=0, active=0, answer=0, n=(int)arrivals.size();\n    while (i<n) {\n        if (j==n || arrivals[i]<=departures[j]) {\n            ++active; ++i; answer=max(answer,active);\n        } else { --active; ++j; }\n    }\n    return answer;\n}', 'O(n log n)','O(n) for input copies'),
        ('jump-game-reachability','Jump Game','Greedy','Greedy basics','Medium',
         'Given a nonempty array of nonnegative integers, start at index 0. nums[i] is the maximum forward jump length from i. Determine whether the final index is reachable. For [2,3,1,1,4], return true; for [3,2,1,0,4], return false.',
         'Do you need every reachable path, or can one boundary summarize all positions reachable so far?',
         'Maintain farthest, the largest reachable index using the positions already visited. If i is beyond farthest, no reachable position can lead to i and the end is unreachable. Otherwise extend farthest to max(farthest, i + nums[i]). Once farthest reaches the final index, return true. A single-element array is reachable without jumping. Empty input is treated as false.',
         '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nbool canJump(const vector<int>& nums) {\n    if (nums.empty()) return false;\n    long long farthest=0;\n    for (int i=0; i<(int)nums.size(); ++i) {\n        if (i>farthest) return false;\n        farthest=max(farthest,(long long)i+nums[i]);\n        if (farthest >= (int)nums.size()-1) return true;\n    }\n    return false;\n}', 'O(n)','O(1)'),
        ('fractional-knapsack','Fractional Knapsack','Greedy','Greedy basics','Medium',
         'Given items with nonnegative values and positive weights, and a nonnegative capacity, maximize total value when any fraction of an item may be taken. Return the maximum achievable value. This version allows splitting items.',
         'If you could take only one extra unit of weight, which available item would provide the most value?',
         'Sort items by decreasing value per unit weight. Take each item completely if it fits, otherwise take the fraction that fills the remaining capacity and stop. If a solution uses weight from a lower-ratio item while some higher-ratio item remains unused, exchanging equal weight cannot decrease value. Repeating this exchange yields the greedy order. This argument depends on fractions being allowed; it does not solve 0/1 knapsack.',
         '#include <vector>\n#include <algorithm>\n#include <stdexcept>\nusing namespace std;\n\nstruct Item { double value, weight; };\ndouble fractionalKnapsack(vector<Item> items, double capacity) {\n    if (capacity<0) throw invalid_argument("negative capacity");\n    for (auto item:items)\n        if (item.weight<=0 || item.value<0) throw invalid_argument("invalid item");\n    sort(items.begin(), items.end(), [](const Item& a,const Item& b) {\n        return a.value/a.weight > b.value/b.weight;\n    });\n    double value=0;\n    for (auto item:items) {\n        double used=min(capacity,item.weight);\n        value += used*item.value/item.weight; capacity-=used;\n        if (capacity<=0) break;\n    }\n    return value;\n}', 'O(n log n)','O(n) input copy'),
    ]
